AppsFlyerTask validateAndLogInAppPurchase(const ValidateAndLogInAppPurchaseParams& params, AppsFlyerCompletion onComplete) {
    const std::string purchaseTypeKey = appsflyer::detail::schemaKey_PurchaseType(params.purchase.purchaseType);
    std::ostringstream oss;
#if (CC_TARGET_PLATFORM == CC_PLATFORM_ANDROID)
    const std::string wirePurchaseType = appsflyer::detail::resolveTransform_androidPurchaseType(purchaseTypeKey);
    oss << "{";
    oss << "\"purchaseType\":\"" << appsflyer::detail::escapeJsonString(wirePurchaseType) << "\"";
    oss << ",\"productId\":\"" << appsflyer::detail::escapeJsonString(params.purchase.productId) << "\"";
    oss << ",\"purchaseToken\":\"" << appsflyer::detail::escapeJsonString(params.purchase.purchaseToken) << "\"";
    oss << ",\"additionalParameters\":" << appsflyer::detail::encodeValueMapJson(params.additionalParameters);
    oss << "}";
#elif (CC_TARGET_PLATFORM == CC_PLATFORM_IOS)
    const std::string wirePurchaseType = appsflyer::detail::resolveTransform_iosPurchaseType(purchaseTypeKey);
    oss << "{";
    oss << "\"product\":{\"productId\":\"" << appsflyer::detail::escapeJsonString(params.purchase.productId) << "\"}";
    oss << ",\"transaction\":{\"transactionId\":\"" << appsflyer::detail::escapeJsonString(params.purchase.transactionId) << "\"";
    oss << ",\"purchaseType\":\"" << appsflyer::detail::escapeJsonString(wirePurchaseType) << "\"}";
    oss << ",\"additionalParameters\":" << appsflyer::detail::encodeValueMapJson(params.additionalParameters);
    oss << "}";
#else
    return detail::unsupportedPlatformTask(std::move(onComplete));
#endif
    const std::string paramsJson = oss.str();
#if (CC_TARGET_PLATFORM == CC_PLATFORM_ANDROID)
    return executeRpc("validateAndLogInAppPurchase", paramsJson, std::move(onComplete));
#elif (CC_TARGET_PLATFORM == CC_PLATFORM_IOS)
    return executeRpc("validateAndLogInAppPurchase", paramsJson, std::move(onComplete));
#endif
}

